import java.util.List;
import java.util.function.Function;

/** Runs every few seconds on a scheduler thread and copies carrier tracking status into our records. */
public class CarrierSync {
    private final ShipmentRepository repository;
    private final Function<String, String> carrierStatus;
    private final List<String> trackedIds;

    public CarrierSync(ShipmentRepository repository, Function<String, String> carrierStatus, List<String> trackedIds) {
        this.repository = repository;
        this.carrierStatus = carrierStatus;
        this.trackedIds = List.copyOf(trackedIds);
    }

    public void tick() {
        for (String id : trackedIds) {
            String status = carrierStatus.apply(id);
            Shipment current = repository.load(id);
            repository.save(current.withStatus(status));
        }
    }
}
import java.util.concurrent.ConcurrentHashMap;

public class InMemoryStore implements KeyValueStore {
    private final ConcurrentHashMap<String, String> data = new ConcurrentHashMap<>();

    @Override
    public String get(String key) {
        return data.get(key);
    }

    @Override
    public void put(String key, String value) {
        data.put(key, value);
    }
}
public interface KeyValueStore {
    String get(String key);

    void put(String key, String value);
}
/** Called from the operator UI when someone tags a shipment (e.g. "fragile", "VIP"). */
public class LabelService {
    private final ShipmentRepository repository;

    public LabelService(ShipmentRepository repository) {
        this.repository = repository;
    }

    public void setLabel(String id, String label) {
        if (label != null && (label.contains("\t") || label.contains("\n"))) {
            throw new IllegalArgumentException("label must be a single line");
        }
        Shipment current = repository.load(id);
        repository.save(current.withLabel(label));
    }
}
public record Shipment(String id, String status, String label) {
    public Shipment withStatus(String newStatus) {
        return new Shipment(id, newStatus, label);
    }

    public Shipment withLabel(String newLabel) {
        return new Shipment(id, status, newLabel);
    }
}
public class ShipmentRepository {
    private static final String PREFIX = "shipment:";

    private final KeyValueStore store;

    public ShipmentRepository(KeyValueStore store) {
        this.store = store;
    }

    public Shipment load(String id) {
        String raw = store.get(PREFIX + id);
        if (raw == null) {
            return new Shipment(id, "UNKNOWN", null);
        }
        String[] parts = raw.split("\t", -1);
        String label = parts[1].isEmpty() ? null : parts[1];
        return new Shipment(id, parts[0], label);
    }

    public void save(Shipment shipment) {
        String label = shipment.label() == null ? "" : shipment.label();
        store.put(PREFIX + shipment.id(), shipment.status() + "\t" + label);
    }
}
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/** Test double: pauses one chosen thread at its first access to a key, so interleavings are reproducible. */
public class GatedStore implements KeyValueStore {
    private final KeyValueStore delegate;
    private final AtomicBoolean fired = new AtomicBoolean();
    private volatile Thread target;
    private volatile String keyPrefix;
    final CountDownLatch reached = new CountDownLatch(1);
    final CountDownLatch release = new CountDownLatch(1);

    public GatedStore(KeyValueStore delegate) {
        this.delegate = delegate;
    }

    void pauseFirstAccess(Thread thread, String prefix) {
        this.keyPrefix = prefix;
        this.target = thread;
    }

    @Override
    public String get(String key) {
        String value = delegate.get(key);
        maybePause(key);
        return value;
    }

    @Override
    public void put(String key, String value) {
        maybePause(key);
        delegate.put(key, value);
    }

    private void maybePause(String key) {
        if (Thread.currentThread() == target && key.startsWith(keyPrefix) && fired.compareAndSet(false, true)) {
            reached.countDown();
            try {
                release.await(3, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

public class ShipmentLabelTest {
    static int failed = 0;

    static void check(boolean cond, String msg) {
        System.out.println((cond ? "ok   - " : "FAIL - ") + msg);
        if (!cond) failed++;
    }

    public static void main(String[] args) throws Exception {
        // 1) one after another: label survives the next carrier sync
        {
            KeyValueStore store = new InMemoryStore();
            ShipmentRepository repo = new ShipmentRepository(store);
            AtomicReference<String> carrier = new AtomicReference<>("PICKED_UP");
            CarrierSync sync = new CarrierSync(repo, id -> carrier.get(), List.of("S1"));
            LabelService labels = new LabelService(repo);
            sync.tick();
            labels.setLabel("S1", "fragile");
            carrier.set("IN_TRANSIT");
            sync.tick();
            Shipment s = repo.load("S1");
            check("fragile".equals(s.label()) && "IN_TRANSIT".equals(s.status()), "sequential: " + s);
        }

        // 2) operator tags the shipment while a carrier sync is in progress
        {
            GatedStore store = new GatedStore(new InMemoryStore());
            ShipmentRepository repo = new ShipmentRepository(store);
            AtomicReference<String> carrier = new AtomicReference<>("PICKED_UP");
            CarrierSync sync = new CarrierSync(repo, id -> carrier.get(), List.of("S1"));
            LabelService labels = new LabelService(repo);
            sync.tick();
            carrier.set("IN_TRANSIT");

            Thread syncThread = new Thread(sync::tick, "carrier-sync");
            store.pauseFirstAccess(syncThread, "shipment:S1");
            syncThread.start();
            store.reached.await(2, TimeUnit.SECONDS);

            Thread uiThread = new Thread(() -> labels.setLabel("S1", "fragile"), "operator-ui");
            uiThread.start();
            uiThread.join(500);
            store.release.countDown();
            syncThread.join(5000);
            uiThread.join(5000);

            Shipment s = repo.load("S1");
            check("fragile".equals(s.label()), "label set during sync is kept (got " + s.label() + ")");
            check("IN_TRANSIT".equals(s.status()), "status updated by sync (got " + s.status() + ")");
        }

        if (failed > 0) {
            System.out.println(failed + " check(s) failed");
            System.exit(1);
        }
        System.out.println("all checks passed");
    }
}

